# Generated by Claudian.
"""Skill: run a web search in the default browser."""

import re

from ai.response_generator import ResponseGenerator
from automation.browser_control import search_in_browser
from multitasking.async_executor import run_in_thread
from skills._base import Skill, SkillMatch, SkillResult

_PATTERNS = [
    re.compile(r"search\s+(?:the\s+)?(?:web|internet|online)\s+(?:for\s+)?(.+)"),
    re.compile(r"(?:google|bing)\s+(.+)"),
    re.compile(r"(?:look\s+up|search\s+for)\s+(.+?)\s+(?:online|on\s+the\s+internet|on\s+google)"),
    re.compile(r"search\s+(.+?)\s+(?:online|on\s+(?:google|the\s+internet|the\s+web))"),
]


class WebSearchSkill(Skill):
    name = "web_search"
    description = "Search the web (Google by default) in the default browser"
    priority = 20

    def __init__(self):
        self._responses = ResponseGenerator()

    def match(self, text: str) -> SkillMatch | None:
        low = text.lower()
        for pat in _PATTERNS:
            m = pat.search(low)
            if m:
                return SkillMatch(confidence=0.92, entities={"query": m.group(1).strip()})
        return None

    async def run(self, text: str, entities: dict) -> SkillResult:
        query = entities.get("query", text)
        await run_in_thread(search_in_browser, query)
        return SkillResult(text=self._responses.web_search_done(query))
